import sys
from collections import defaultdict

def main():
    data = sys.stdin.buffer.read().split()
    idx = 0
    N = int(data[idx]); idx += 1
    W = int(data[idx]); idx += 1

    cols = [[] for _ in range(W + 1)]  # 1-indexed
    for i in range(N):
        x = int(data[idx]); idx += 1
        y = int(data[idx]); idx += 1
        cols[x].append((y, i))

    rank = [0] * N
    min_c = None
    for x in range(1, W + 1):
        cols[x].sort()
        cx = len(cols[x])
        if min_c is None or cx < min_c:
            min_c = cx
        for r, (y, bi) in enumerate(cols[x], start=1):
            rank[bi] = r

    if min_c is None:
        min_c = 0

    # R[k] = max over columns of k-th smallest Y, for k = 1..min_c
    R = [0] * (min_c + 1)
    for x in range(1, W + 1):
        if not cols[x]:
            continue
        for k in range(1, min_c + 1):
            y_k = cols[x][k-1][0]
            if y_k > R[k]:
                R[k] = y_k

    Q = int(data[idx]); idx += 1
    out = []
    for _ in range(Q):
        T = int(data[idx]); idx += 1
        A = int(data[idx]) - 1; idx += 1
        j = rank[A]
        if j > min_c:
            out.append("Yes")
        else:
            if T < R[j]:
                out.append("Yes")
            else:
                out.append("No")

    sys.stdout.write('\n'.join(out) + '\n')

main()

